"use strict";exports.accuracy=function(t){return null===t?"暂无有效样本":(100*t).toFixed(1)+"%"},exports.beijingDate=function(t=Date.now()){return new Date(t+288e5).toISOString().slice(0,10)},exports.reportPeriod=function(t,e){if(!/^\d{4}-\d{2}-\d{2}$/.test(t))return null;const[n,r,i]=t.split("-").map(Number);if(n<2e3||n>9998)return null;const s=new Date(Date.UTC(n,r-1,i));if(s.toISOString().slice(0,10)!==t)return null;if("weekly"===e?s.setUTCDate(s.getUTCDate()-(s.getUTCDay()+6)%7):s.setUTCDate(1),s.getUTCFullYear()<2e3)return null;const l=s.toISOString().slice(0,10);"weekly"===e?s.setUTCDate(s.getUTCDate()+7):s.setUTCMonth(s.getUTCMonth()+1);const o=s.toISOString().slice(0,10);return s.setUTCDate(s.getUTCDate()-1),{start:l,end:o,last:s.toISOString().slice(0,10)}};
